def _get_captured_output(self):
    if self._output_file.closed:
        return
    text = self._output_file.get()
    if isinstance(text, bytes):
        text = text.decode("utf-8", "replace")
    if self.captured_out:
        text = self.captured_out + text
    if self.captured_out_filter is not None:
        text = self.captured_out_filter(text)
    self.captured_out = text

def _start_heartbeat(self):
    self.run_logger.debug("Starting Heartbeat")
    if self.beat_interval > 0:
        self._stop_heartbeat_event, self._heartbeat = IntervalTimer.create(
            self._emit_heartbeat, self.beat_interval
        )
        self._heartbeat.start()

def get_last_metrics(self):
    """Read all measurement events since last call of the method.

    :return List[ScalarMetricLogEntry]
    """
    read_up_to = self._logged_metrics.qsize()
    messages = []
    for i in range(read_up_to):
        try:
            messages.append(self._logged_metrics.get_nowait())
        except Empty:
            pass
    return messages

def _warn_about_suspicious_changes(self):
    for add in sorted(self.config_mods.added):
        if not set(iter_prefixes(add)).intersection(self.captured_args):
            if self.path:
                add = join_paths(self.path, add)
            raise ConfigAddedError(add, config=self.config)
        else:
            self.logger.warning('Added new config entry: "%s"' % add)

    for key, (type_old, type_new) in self.config_mods.typechanged.items():
        if type_old in (int, float) and type_new in (int, float):
            continue
        self.logger.warning(
            'Changed type of config entry "%s" from %s to %s'
            % (key, type_old.__name__, type_new.__name__)
        )

    for cfg_summary in self.summaries:
        for key in cfg_summary.ignored_fallbacks:
            self.logger.warning(
                'Ignored attempt to set value of "%s", because it is an '
                "ingredient." % key
            )

def join_paths(*parts):
    """Join different parts together to a valid dotted path."""
    return ".".join(str(p).strip(".") for p in parts if p)

