def get_inheritors(cls):
    """Get a set of all classes that inherit from the given class."""
    subclasses = set()
    work = [cls]
    while work:
        parent = work.pop()
        for child in parent.__subclasses__():
            if child not in subclasses:
                subclasses.add(child)
                work.append(child)
    return subclasses

def insert(self):
    import pymongo.errors

    if self.overwrite:
        return self.save()

    autoinc_key = self.run_entry.get("_id") is None
    while True:
        if autoinc_key:
            c = self.runs.find({}, {"_id": 1})
            c = c.sort("_id", pymongo.DESCENDING).limit(1)
            self.run_entry["_id"] = (
                c.next()["_id"] + 1 if self.runs.count_documents({}, limit=1) else 1
            )
        try:
            self.runs.insert_one(self.run_entry)
            return
        except pymongo.errors.InvalidDocument as e:
            raise ObserverError(
                "Run contained an unserializable entry."
                "(most likely in the info)\n{}".format(e)
            ) from e
        except pymongo.errors.DuplicateKeyError:
            if not autoinc_key:
                raise

