def save_sources(self, ex_info):
    base_dir = ex_info["base_dir"]
    source_info = []
    for source_name, md5 in ex_info["sources"]:
        abs_path = os.path.join(base_dir, source_name)
        file = self.fs.find_one({"filename": abs_path, "md5": md5})
        if file:
            _id = file._id
        else:
            with open(abs_path, "rb") as f:
                _id = self.fs.put(f, filename=abs_path)
        source_info.append([source_name, _id])
    return source_info

def get(self):
    if self.final is None:
        self.buffer.seek(self.read_position)
        value = self.buffer.read()
        self.read_position = self.buffer.tell()
        return value
    else:
        value = self.final
        self.final = None
        return value

