def _create_config_dict(cfg_or_file, kw_conf):
    if cfg_or_file is not None and kw_conf:
        raise ValueError(
            "cannot combine keyword config with " "positional argument"
        )
    if cfg_or_file is None:
        if not kw_conf:
            raise ValueError("attempted to add empty config")
        return ConfigDict(kw_conf)
    elif isinstance(cfg_or_file, dict):
        return ConfigDict(cfg_or_file)
    elif isinstance(cfg_or_file, str):
        if not os.path.exists(cfg_or_file):
            raise OSError("File not found {}".format(cfg_or_file))
        abspath = os.path.abspath(cfg_or_file)
        return ConfigDict(load_config_file(abspath))
    else:
        raise TypeError("Invalid argument type {}".format(type(cfg_or_file)))

def distribute_named_configs(scaffolding, named_configs):
    for ncfg in named_configs:
        if os.path.exists(ncfg):
            scaffolding[""].use_named_config(ncfg)
        else:
            path, _, cfg_name = ncfg.rpartition(".")
            if path not in scaffolding:
                raise KeyError(
                    'Ingredient for named config "{}" not found'.format(ncfg)
                )
            scaffolding[path].use_named_config(cfg_name)

def get_scaffolding_and_config_name(named_config, scaffolding):
    if os.path.exists(named_config):
        path, cfg_name = "", named_config
    else:
        path, _, cfg_name = named_config.rpartition(".")

        if path not in scaffolding:
            raise KeyError(
                'Ingredient for named config "{}" not found'.format(named_config)
            )
    scaff = scaffolding[path]
    return scaff, cfg_name

def _format_named_config(indent, path, named_config):
    indent = " " * indent
    assign = path
    if hasattr(named_config, "__doc__") and named_config.__doc__ is not None:
        doc_string = named_config.__doc__
        if doc_string.strip().count("\n") == 0:
            assign += COLOR_DOC + "   # {}".format(doc_string.strip()) + ENDC
        else:
            doc_string = doc_string.replace("\n", "\n" + indent)
            assign += (
                COLOR_DOC + '\n{}"""{}"""'.format(indent + "  ", doc_string) + ENDC
            )
    return indent + assign

def _format_named_configs(named_configs, indent=2):
    lines = ["Named Configurations (" + COLOR_DOC + "doc" + ENDC + "):"]
    for path, named_config in named_configs.items():
        lines.append(_format_named_config(indent, path, named_config))
    if len(lines) < 2:
        lines.append(" " * indent + "No named configs")
    return "\n".join(lines)

def gather_ingredients_topological(ingredient):
    sub_ingredients = defaultdict(int)
    for sub_ing, depth in ingredient.traverse_ingredients():
        sub_ingredients[sub_ing] = max(sub_ingredients[sub_ing], depth)
    return sorted(sub_ingredients, key=lambda x: -sub_ingredients[x])

def track(cls, ingredient):
    try:
        yield
    except CircularDependencyError as e:
        if not e.__circular_dependency_handled__:
            if ingredient in e.__ingredients__:
                e.__circular_dependency_handled__ = True
            e.__ingredients__.append(ingredient)
        raise e

def get_py_file_if_possible(pyc_name):
    """Try to retrieve a X.py file for a given X.py[c] file."""
    if pyc_name.endswith((".py", ".so", ".pyd", ".ipynb")):
        return pyc_name
    assert pyc_name.endswith(".pyc")
    non_compiled_file = pyc_name[:-1]
    if os.path.exists(non_compiled_file):
        return non_compiled_file
    return pyc_name

def create(filename, save_git_info=True):
    if not filename or not os.path.exists(filename):
        raise ValueError('invalid filename or file not found "{}"'.format(filename))

    main_file = get_py_file_if_possible(os.path.abspath(filename))
    repo, commit, is_dirty = get_commit_if_possible(main_file, save_git_info)
    return Source(main_file, get_digest(main_file), repo, commit, is_dirty)

def get_main_file(globs, save_git_info):
    filename = globs.get("__file__")

    if filename is None:
        experiment_path = os.path.abspath(os.path.curdir)
        main = None
    else:
        main = Source.create(globs.get("__file__"), save_git_info)
        experiment_path = os.path.dirname(main.filename)
    return experiment_path, main

def iterate_all_python_files(base_path):
    # TODO support ignored directories/files
    for dirname, subdirlist, filelist in os.walk(base_path):
        if "__pycache__" in dirname:
            continue
        for filename in filelist:
            if filename.endswith(".py"):
                yield os.path.join(base_path, dirname, filename)

def get_sources_from_local_dir(globs, base_path, save_git_info):
    return {
        Source.create(filename, save_git_info)
        for filename in iterate_all_python_files(base_path)
    }

def get_digest(filename):
    """Compute the MD5 hash for a given file."""
    h = hashlib.md5()
    with open(filename, "rb") as f:
        data = f.read(1 * MB)
        while data:
            h.update(data)
            data = f.read(1 * MB)
        return h.hexdigest()

def get_or_create(cls, filename, session):
    md5sum = get_digest(filename)
    instance = (
        session.query(cls).filter_by(filename=filename, md5sum=md5sum).first()
    )
    if instance:
        return instance
    with open(filename, "rb") as f:
        return cls(filename=filename, md5sum=md5sum, content=f.read())

def to_json(self, base_dir=None):
    if base_dir:
        return (
            os.path.relpath(self.filename, os.path.realpath(base_dir)),
            self.digest,
        )
    else:
        return self.filename, self.digest

def to_json(self):
    return {
        "name": self.name,
        "base_dir": self.base_dir,
        "sources": [s.to_json() for s in self.sources],
        "repositories": [r.to_json() for r in self.repositories],
        "dependencies": [d.to_json() for d in self.dependencies],
    }

def __eq__(self, other):
    if isinstance(other, Source):
        return self.filename == other.filename
    elif isinstance(other, str):
        return self.filename == other
    else:
        return False

def __eq__(self, other):
    if isinstance(other, SqlObserver):
        # fixme: this will probably fail to detect two equivalent engines
        return self.engine == other.engine and self.session == other.session
    return False

def __eq__(self, other):
    if isinstance(other, GoogleCloudStorageObserver):
        return self.bucket_id == other.bucket_id and self.basedir == other.basedir
    else:
        return False

def __eq__(self, other):
    if isinstance(other, S3Observer):
        return self.bucket == other.bucket and self.basedir == other.basedir
    else:
        return False

def __eq__(self, other):
    if isinstance(other, FileStorageObserver):
        return self.basedir == other.basedir
    return False

def __eq__(self, other):
    if isinstance(other, MongoObserver):
        return self.runs == other.runs
    return False

def __eq__(self, other):
    if isinstance(other, TinyDbObserver):
        return self.runs.all() == other.runs.all()
    return False

def __init__(self, name, version):
    self.name = name
    self.version = version

def freeze_keys(self):
    if self.__frozen_keys:
        return
    self.__frozen_keys = True
    for v in self.values():
        if isinstance(v, FrozenKeyMunch):
            v.freeze_keys()

def __deepcopy__(self, memodict=None):
    obj = self.__class__.fromDict(self.toDict())
    if self.__frozen_keys:
        obj.freeze_keys()
    return obj

def __eq__(self, other):
    if isinstance(other, PackageDependency):
        return self.name == other.name
    else:
        return False

def _iterate_marked(cfg, config_mods):
    for path, value in iterate_flattened_separately(cfg, ["__doc__"]):
        if value is PATHCHANGE:
            yield path, PathEntry(
                key=path.rpartition(".")[2],
                added=path in config_mods.added,
                modified=path in config_mods.modified,
                typechanged=config_mods.typechanged.get(path),
                doc=config_mods.docs.get(path),
            )
        else:
            yield path, ConfigEntry(
                key=path.rpartition(".")[2],
                value=value,
                added=path in config_mods.added,
                modified=path in config_mods.modified,
                typechanged=config_mods.typechanged.get(path),
                doc=config_mods.docs.get(path),
            )

def create(cls, mod):
    if not cls.modname_to_dist:
        # some packagenames don't match the module names (e.g. PyYAML)
        # so we set up a dict to map from module name to package name
        for dist in pkg_resources.working_set:
            try:
                toplevel_names = dist._get_metadata("top_level.txt")
                for tln in toplevel_names:
                    cls.modname_to_dist[tln] = dist.project_name, dist.version
            except Exception:
                pass

    name, version = cls.modname_to_dist.get(mod.__name__, (mod.__name__, None))

    return PackageDependency(name, version)

def convert_path_to_module_parts(path):
    """Convert path to a python file into list of module names."""
    module_parts = list(path.parts)
    if module_parts[-1] in ["__init__.py", "__init__.pyc"]:
        # remove trailing __init__.py
        module_parts = module_parts[:-1]
    else:
        # remove file extension
        module_parts[-1], _ = os.path.splitext(module_parts[-1])
    return module_parts

def iterate_imported_modules(globs):
    checked_modules = set(MODULE_BLACKLIST)
    for glob in globs.values():
        if isinstance(glob, module):
            mod_path = glob.__name__
        elif hasattr(glob, "__module__"):
            mod_path = glob.__module__
        else:
            continue  # pragma: no cover

        if not mod_path:
            continue

        for modname in iter_prefixes(mod_path):
            if modname in checked_modules:
                continue
            checked_modules.add(modname)
            mod = sys.modules.get(modname)
            if mod is not None:
                yield modname, mod

def iterate_sys_modules():
    items = list(sys.modules.items())
    for modname, mod in items:
        if modname not in MODULE_BLACKLIST and mod is not None:
            yield modname, mod

def get_sources_from_modules(module_iterator, base_path, save_git_info):
    sources = set()
    for modname, mod in module_iterator:
        # hasattr doesn't work with python extensions
        if not getattr(mod, "__file__", None):
            continue

        filename = os.path.abspath(mod.__file__)
        if filename not in sources and is_local_source(filename, modname, base_path):
            s = Source.create(filename, save_git_info)
            sources.add(s)
    return sources

def get_dependencies_from_modules(module_iterator, base_path):
    dependencies = set()
    for modname, mod in module_iterator:
        # hasattr doesn't work with python extensions
        if getattr(mod, "__file__", None) and is_local_source(
            os.path.abspath(mod.__file__), modname, base_path
        ):
            continue
        if modname.startswith("_") or "." in modname:
            continue

        try:
            pdep = PackageDependency.create(mod)
            if pdep.version is not None:
                dependencies.add(pdep)
        except AttributeError:
            pass
    return dependencies

def get_sources_from_imported_modules(globs, base_path, save_git_info):
    return get_sources_from_modules(
        iterate_imported_modules(globs), base_path, save_git_info
    )

def module_exists(modname):
    """Checks if a module exists without actually importing it."""
    try:
        return pkgutil.find_loader(modname) is not None
    except ImportError:
        # TODO: Temporary fix for tf 1.14.0.
        # Should be removed once fixed in tf.
        return True

def flush():
    """Try to flush all stdio buffers, both from python and from C."""
    try:
        sys.stdout.flush()
        sys.stderr.flush()
    except (AttributeError, ValueError, OSError):
        pass  # unsupported
    try:
        libc.fflush(None)
    except (AttributeError, ValueError, OSError):
        pass  # unsupported

def get_stdcapturer(mode=None):
    mode = mode if mode is not None else SETTINGS.CAPTURE_MODE
    capture_options = {"no": no_tee, "fd": tee_output_fd, "sys": tee_output_python}
    if mode not in capture_options:
        raise KeyError(
            "Unknown capture mode '{}'. Available options are {}".format(
                mode, sorted(capture_options.keys())
            )
        )
    return mode, capture_options[mode]

def no_tee():
    out = CapturedStdout(StringIO())
    try:
        yield out
    finally:
        out.finalize()

def write(self, data):
    self.__wrapped__.write(data)
    self._self_out.write(data)

def set_up_seed(self, rnd=None):
    if self.seed is not None:
        return

    self.seed = self.config.get("seed")
    if self.seed is None:
        self.seed = get_seed(rnd)

    self.rnd = create_rnd(self.seed)

    if self.generate_seed:
        self.config["seed"] = self.seed

    if "seed" in self.config and "seed" in self.config_mods.added:
        self.config_mods.modified.add("seed")
        self.config_mods.added -= {"seed"}

    # Hierarchically set the seed of proper subrunners
    for subrunner_path, subrunner in reversed(list(self.subrunners.items())):
        if is_prefix(self.path, subrunner_path):
            subrunner.set_up_seed(self.rnd)

def finalize_initialization(self, run):
    # look at seed again, because it might have changed during the
    # configuration process
    if "seed" in self.config:
        self.seed = self.config["seed"]
    self.rnd = create_rnd(self.seed)

    for cfunc in self._captured_functions:
        # Setup the captured function
        cfunc.logger = self.logger.getChild(cfunc.__name__)
        seed = get_seed(self.rnd)
        cfunc.rnd = create_rnd(seed)
        cfunc.run = run
        cfunc.config = get_by_dotted_path(
            self.get_fixture(), cfunc.prefix, default={}
        )

        # Make configuration read only if enabled in settings
        if SETTINGS.CONFIG.READ_ONLY_CONFIG:
            cfunc.config = make_read_only(cfunc.config)

    if not run.force:
        self._warn_about_suspicious_changes()

def get_seed(rnd=None):
    if rnd is None:
        return random.randint(*SEEDRANGE)
    else:
        try:
            return rnd.integers(*SEEDRANGE, dtype=int)
        except Exception:
            return rnd.randint(*SEEDRANGE)

def create_rnd(seed):
    assert isinstance(seed, int), "Seed has to be integer but was {} {}".format(
        repr(seed), type(seed)
    )
    if opt.has_numpy:
        if SETTINGS.CONFIG.NUMPY_RANDOM_LEGACY_API:
            return opt.np.random.RandomState(seed)
        else:
            return opt.np.random.default_rng(seed)
    else:
        return random.Random(seed)

def make_read_only(o):
    """Makes objects read-only.

    Converts every `list` and `dict` into `ReadOnlyList` and `ReadOnlyDict` in
    a nested structure of `list`s, `dict`s and `tuple`s. Does not modify `o`
    but returns the converted structure.
    """
    if type(o) == dict:
        return ReadOnlyDict({k: make_read_only(v) for k, v in o.items()})
    elif type(o) == list:
        return ReadOnlyList([make_read_only(v) for v in o])
    elif type(o) == tuple:
        return tuple(map(make_read_only, o))
    else:
        return o

def gather_fallbacks(self):
    fallback = {"_log": self.logger}
    for sr_path, subrunner in self.subrunners.items():
        if self.path and is_prefix(self.path, sr_path):
            path = sr_path[len(self.path) :].strip(".")
            set_by_dotted_path(fallback, path, subrunner.config)
        else:
            set_by_dotted_path(fallback, sr_path, subrunner.config)

    # dogmatize to make the subrunner configurations read-only
    self.fallback = dogmatize(fallback)
    self.fallback.revelation()

def get_configuration(scaffolding):
    config = {}
    for sc_path, scaffold in reversed(list(scaffolding.items())):
        if not scaffold.config:
            continue
        if sc_path:
            set_by_dotted_path(config, sc_path, scaffold.config)
        else:
            config.update(scaffold.config)
    return config

def find_best_match(path, prefixes):
    """Find the Ingredient that shares the longest prefix with path."""
    path_parts = path.split(".")
    for p in prefixes:
        if len(p) <= len(path_parts) and p == path_parts[: len(p)]:
            return ".".join(p), ".".join(path_parts[len(p) :])
    return "", path

def distribute_presets(sc_path, prefixes, scaffolding, config_updates):
    for path, value in iterate_flattened(config_updates):
        if sc_path:
            path = sc_path + "." + path
        scaffold_name, suffix = find_best_match(path, prefixes)
        scaff = scaffolding[scaffold_name]
        set_by_dotted_path(scaff.presets, suffix, value)

def distribute_config_updates(prefixes, scaffolding, config_updates):
    for path, value in iterate_flattened(config_updates):
        scaffold_name, suffix = find_best_match(path, prefixes)
        scaff = scaffolding[scaffold_name]
        set_by_dotted_path(scaff.config_updates, suffix, value)

def iterate_flattened(d):
    """
    Recursively iterate over the items of a dictionary.

    Provides a full dotted paths for every leaf.
    """
    for key in sorted(d.keys()):
        value = d[key]
        if isinstance(value, dict) and value:
            for k, v in iterate_flattened(d[key]):
                yield join_paths(key, k), v
        else:
            yield key, value

def convert_to_nested_dict(dotted_dict):
    """Convert a dict with dotted path keys to corresponding nested dict."""
    nested_dict = {}
    for k, v in iterate_flattened(dotted_dict):
        set_by_dotted_path(nested_dict, k, v)
    return nested_dict

def run_named_config(self, config_name):
    if os.path.isfile(config_name):
        nc = ConfigDict(load_config_file(config_name))
    else:
        if config_name not in self.named_configs:
            raise NamedConfigNotFoundError(
                named_config=config_name,
                available_named_configs=tuple(self.named_configs.keys()),
            )
        nc = self.named_configs[config_name]

    cfg = nc(
        fixed=self.get_config_updates_recursive(),
        preset=self.presets,
        fallback=self.fallback,
    )

    return undogmatize(cfg)

def get_config_updates_recursive(self):
    config_updates = self.config_updates.copy()
    for sr_path, subrunner in self.subrunners.items():
        if not is_prefix(self.path, sr_path):
            continue
        update = subrunner.get_config_updates_recursive()
        if update:
            config_updates[rel_path(self.path, sr_path)] = update
    return config_updates

def is_prefix(pre_path, path):
    """Return True if pre_path is a path-prefix of path."""
    pre_path = pre_path.strip(".")
    path = path.strip(".")
    return not pre_path or path.startswith(pre_path + ".")

def rel_path(base, path):
    """Return path relative to base."""
    if base == path:
        return ""
    assert is_prefix(base, path), "{} not a prefix of {}".format(base, path)
    return path[len(base) :].strip(".")

def get_config_modifications(self):
    self.config_mods = ConfigSummary(
        added={key for key, value in iterate_flattened(self.config_updates)}
    )
    for cfg_summary in self.summaries:
        self.config_mods.update_from(cfg_summary)

def update_from(self, config_mod, path=""):
    added = config_mod.added
    updated = config_mod.modified
    typechanged = config_mod.typechanged
    self.added &= {join_paths(path, a) for a in added}
    self.modified |= {join_paths(path, u) for u in updated}
    self.typechanged.update(
        {join_paths(path, k): v for k, v in typechanged.items()}
    )
    self.ensure_coherence()
    for k, v in config_mod.docs.items():
        if not self.docs.get(k, ""):
            self.docs[k] = v

def run_config_hooks(self, config, command_name, logger):
    final_cfg_updates = {}
    for ch in self.config_hooks:
        cfg_upup = ch(deepcopy(config), command_name, logger)
        if cfg_upup:
            recursive_update(final_cfg_updates, cfg_upup)
    recursive_update(final_cfg_updates, self.config_updates)
    return final_cfg_updates

def recursive_update(d, u):
    """
    Given two dictionaries d and u, update dict d recursively.

    E.g.:
    d = {'a': {'b' : 1}}
    u = {'c': 2, 'a': {'d': 3}}
    => {'a': {'b': 1, 'd': 3}, 'c': 2}
    """
    for k, v in u.items():
        if isinstance(v, collections.abc.Mapping):
            r = recursive_update(d.get(k, {}), v)
            d[k] = r
        else:
            d[k] = u[k]
    return d

def get_command(scaffolding, command_path):
    path, _, command_name = command_path.rpartition(".")
    if path not in scaffolding:
        raise KeyError('Ingredient for command "%s" not found.' % command_path)

    if command_name in scaffolding[path].commands:
        return scaffolding[path].commands[command_name]
    else:
        if path:
            raise KeyError(
                'Command "%s" not found in ingredient "%s"' % (command_name, path)
            )
        else:
            raise KeyError('Command "%s" not found' % command_name)

def initialize_logging(experiment, scaffolding, log_level=None):
    if experiment.logger is None:
        root_logger = create_basic_stream_logger()
    else:
        root_logger = experiment.logger

    for sc_path, scaffold in scaffolding.items():
        if sc_path:
            scaffold.logger = root_logger.getChild(sc_path)
        else:
            scaffold.logger = root_logger

    # set log level
    if log_level is not None:
        try:
            lvl = int(log_level)
        except ValueError:
            lvl = log_level
        root_logger.setLevel(lvl)

    return root_logger, root_logger.getChild(experiment.path)

def get_config_modifications(scaffolding):
    config_modifications = ConfigSummary()
    for sc_path, scaffold in scaffolding.items():
        config_modifications.update_add(scaffold.config_mods, path=sc_path)
    return config_modifications

def update_add(self, config_mod, path=""):
    added = config_mod.added
    updated = config_mod.modified
    typechanged = config_mod.typechanged
    self.added |= {join_paths(path, a) for a in added}
    self.modified |= {join_paths(path, u) for u in updated}
    self.typechanged.update(
        {join_paths(path, k): v for k, v in typechanged.items()}
    )
    self.docs.update(
        {
            join_paths(path, k): v
            for k, v in config_mod.docs.items()
            if path == "" or k != "seed"
        }
    )
    self.ensure_coherence()

def ensure_coherence(self):
    # make sure parent paths show up as updated appropriately
    self.modified |= {p for a in self.added for p in iter_prefixes(a)}
    self.modified |= {p for u in self.modified for p in iter_prefixes(u)}
    self.modified |= {p for t in self.typechanged for p in iter_prefixes(t)}

    # make sure there is no overlap
    self.added -= set(self.typechanged.keys())
    self.modified -= set(self.typechanged.keys())
    self.modified -= self.added

def __str__(self):
    return super().__str__() + "->".join(
        [i.path for i in reversed(self.__ingredients__)]
    )

def encode(self, obj):
    address = self.fs.put(obj)
    return json.dumps(address.id)

def track(cls, config, prefix=None):
    try:
        yield
    except ConfigError as e:
        if not e.__prefix_handled__:
            if prefix:
                e.__conflicting_configs__ = (
                    join_paths(prefix, str(c)) for c in e.__conflicting_configs__
                )
            e.__config__ = config
            e.__prefix_handled__ = True
        raise e

def create_captured_function(function, prefix=None):
    sig = Signature(function)
    function.signature = sig
    function.uses_randomness = "_seed" in sig.arguments or "_rnd" in sig.arguments
    function.logger = None
    function.config = {}
    function.rnd = None
    function.run = None
    function.prefix = prefix
    return captured_function(function)

def __str__(self):
    s = super().__str__()
    if self.print_suggestions:
        possible_keys = set(self.captured_args) - self.SPECIAL_ARGS
        if possible_keys:
            s += "\nPossible config keys are: {}".format(possible_keys)
    return s

def format_filtered_stacktrace(filter_traceback="default"):
    """
    Returns the traceback as `string`.

    `filter_traceback` can be one of:
        - 'always': always filter out sacred internals
        - 'default': Default behaviour: filter out sacred internals
                if the exception did not originate from within sacred, and
                print just the internal stack trace otherwise
        - 'never': don't filter, always print full traceback
        - All other values will fall back to 'never'.
    """
    exc_type, exc_value, exc_traceback = sys.exc_info()
    # determine if last exception is from sacred
    current_tb = exc_traceback
    while current_tb.tb_next is not None:
        current_tb = current_tb.tb_next

    if filter_traceback == "default" and _is_sacred_frame(current_tb.tb_frame):
        # just print sacred internal trace
        header = [
            "Exception originated from within Sacred.\n"
            "Traceback (most recent calls):\n"
        ]
        texts = tb.format_exception(exc_type, exc_value, current_tb)
        return "".join(header + texts[1:]).strip()
    elif filter_traceback in ("default", "always"):
        # print filtered stacktrace
        tb_exception = FilteredTracebackException(
            exc_type, exc_value, exc_traceback, limit=None
        )
        return "".join(tb_exception.format())
    elif filter_traceback == "never":
        # print full stacktrace
        return "\n".join(tb.format_exception(exc_type, exc_value, exc_traceback))
    else:
        raise ValueError("Unknown value for filter_traceback: " + filter_traceback)

def format_sacred_error(e, short_usage):
    lines = []
    if e.print_usage:
        lines.append(short_usage)
    if e.print_traceback:
        lines.append(format_filtered_stacktrace(e.filter_traceback))
    else:
        lines.append("\n".join(tb.format_exception_only(type(e), e)))
    return "\n".join(lines)

def _walk_value(self, obj):
    if obj.__cause__:
        obj.__cause__.__traceback__ = self._filter_tb(obj.__cause__.__traceback__)
        self._walk_value(obj.__cause__)
    if obj.__context__:
        obj.__context__.__traceback__ = self._filter_tb(
            obj.__context__.__traceback__
        )
        self._walk_value(obj.__context__)

def _filter_tb(self, tb):
    filtered_tb = []
    while tb is not None:
        if not _is_sacred_frame(tb.tb_frame):
            filtered_tb.append(tb)
        tb = tb.tb_next
    if len(filtered_tb) >= 2:
        for i in range(1, len(filtered_tb)):
            filtered_tb[i - 1].tb_next = filtered_tb[i]
    filtered_tb[-1].tb_next = None
    return filtered_tb[0]

def format(self, *, chain=True):
    for line in super().format(chain=chain):
        if line == "Traceback (most recent call last):\n":
            yield "Traceback (most recent calls WITHOUT Sacred internals):\n"
        else:
            yield line

def get_failed_text(self):
    return self.failed_text.format(
        backtrace="".join(self.run["fail_trace"]), **self.run
    )

def iterate_flattened_separately(dictionary, manually_sorted_keys=None):
    """
    Recursively iterate over the items of a dictionary in a special order.

    First iterate over manually sorted keys and then over all items that are
    non-dictionary values (sorted by keys), then over the rest
    (sorted by keys), providing full dotted paths for every leaf.
    """
    manually_sorted_keys = manually_sorted_keys or []

    def get_order(key_and_value):
        key, value = key_and_value
        if key in manually_sorted_keys:
            return 0, manually_sorted_keys.index(key)
        elif not is_non_empty_dict(value):
            return 1, key
        else:
            return 2, key

    for key, value in sorted(dictionary.items(), key=get_order):
        if is_non_empty_dict(value):
            yield key, PATHCHANGE
            for k, val in iterate_flattened_separately(value, manually_sorted_keys):
                yield join_paths(key, k), val
        else:
            yield key, value

def get_order(key_and_value):
    key, value = key_and_value
    if key in manually_sorted_keys:
        return 0, manually_sorted_keys.index(key)
    elif not is_non_empty_dict(value):
        return 1, key
    else:
        return 2, key

def apply_backspaces_and_linefeeds(text):
    """
    Interpret backspaces and linefeeds in text like a terminal would.

    Interpret text like a terminal by removing backspace and linefeed
    characters and applying them line by line.

    If final line ends with a carriage it keeps it to be concatenable with next
    output chunk.
    """
    orig_lines = text.split("\n")
    orig_lines_len = len(orig_lines)
    new_lines = []
    for orig_line_idx, orig_line in enumerate(orig_lines):
        chars, cursor = [], 0
        orig_line_len = len(orig_line)
        for orig_char_idx, orig_char in enumerate(orig_line):
            if orig_char == "\r" and (
                orig_char_idx != orig_line_len - 1
                or orig_line_idx != orig_lines_len - 1
            ):
                cursor = 0
            elif orig_char == "\b":
                cursor = max(0, cursor - 1)
            else:
                if (
                    orig_char == "\r"
                    and orig_char_idx == orig_line_len - 1
                    and orig_line_idx == orig_lines_len - 1
                ):
                    cursor = len(chars)
                if cursor == len(chars):
                    chars.append(orig_char)
                else:
                    chars[cursor] = orig_char
                cursor += 1
        new_lines.append("".join(chars))
    return "\n".join(new_lines)

def module_is_in_cache(modname):
    """Checks if a module was imported before (is in the import cache)."""
    return modname in sys.modules

def set_global_seed(seed):
    random.seed(seed)
    if opt.has_numpy:
        opt.np.random.seed(seed)
    if module_is_in_cache("tensorflow"):
        tf = opt.get_tensorflow()
        tf.set_random_seed(seed)
    if module_is_in_cache("torch"):
        import torch

        torch.manual_seed(seed)
        if torch.cuda.is_available():
            torch.cuda.manual_seed_all(seed)

def started_event(self, *args, **kwargs):
    self._queue = Queue()
    self._stop_worker_event, self._worker = IntervalTimer.create(
        self._run, interval=self._interval
    )
    self._worker.start()

    # Putting the started event on the queue makes no sense
    # as it is required for initialization of the covered observer.
    return self._covered_observer.started_event(*args, **kwargs)

def _run(self):
    """Empty the queue every interval."""
    while not self._queue.empty():
        try:
            event = self._queue.get()
        except IndexError:
            # Currently there is no event on the queue so
            # just go back to sleep.
            pass
        else:
            try:
                method = getattr(self._covered_observer, event.name)
            except NameError:
                # The covered observer does not implement an event handler
                # for the event, so just discard the message.
                self._queue.task_done()
            else:
                while True:
                    try:
                        method(*event.args, **event.kwargs)
                    except:
                        # Something went wrong during the processing of
                        # the event so wait for some time and
                        # then try again.
                        logger.debug(
                            "Error while processing event. Trying again.\n{}".format(
                                traceback.format_exc()
                            )
                        )
                        # logging.debug(f"""Error while processing event. Trying again.
                        # {traceback.format_exc()}""")

                        self._stop_worker_event.wait(self._retry_interval)
                        continue
                    else:
                        self._queue.task_done()
                        break

def _format_entry(indent, entry):
    color = ""
    indent = " " * indent
    if entry.typechanged:
        color = COLOR_TYPECHANGED  # red
    elif entry.added:
        color = COLOR_ADDED  # green
    elif entry.modified:
        color = COLOR_MODIFIED  # blue
    if entry.key == "__doc__":
        color = COLOR_DOC  # grey
        doc_string = entry.value.replace("\n", "\n" + indent)
        assign = '{}"""{}"""'.format(indent, doc_string)
    elif isinstance(entry, ConfigEntry):
        assign = indent + entry.key + " = " + PRINTER.pformat(entry.value)
    else:  # isinstance(entry, PathEntry):
        assign = indent + entry.key + ":"
    if entry.doc:
        doc_string = COLOR_DOC + "# " + entry.doc + ENDC
        if len(assign) <= 35:
            assign = "{:<35}  {}".format(assign, doc_string)
        else:
            assign += "    " + doc_string
    end = ENDC if color else ""
    return color + assign + end

def _format_config(cfg, config_mods):
    lines = ["Configuration " + LEGEND + ":"]
    for path, entry in _iterate_marked(cfg, config_mods):
        indent = 2 + 2 * path.count(".")
        lines.append(_format_entry(indent, entry))
    return "\n".join(lines)

def _check_can_set(self, key, value):
    if not self.__frozen_keys:
        return

    # Don't allow unknown keys
    if key not in self:
        raise SettingError(
            f"Unknown setting: {key}. Possible keys are: " f"{list(self.keys())}"
        )

    # Don't allow setting keys that represent nested settings
    if isinstance(self[key], Munch) and not isinstance(value, Munch):
        # We don't want to overwrite a munch mapping. This is the easiest
        # solution and closest to the original implementation where setting
        # a setting with a dict would likely at some point cause an
        # exception
        raise SettingError(
            f"Can't set this setting ({key}) to a non-munch value "
            f"{value}, it is a nested setting!"
        )

def __setitem__(self, key, value):
    self._check_can_set(key, value)
    super().__setitem__(key, value)

def __setattr__(self, key, value):
    self._check_can_set(key, value)
    super().__setattr__(key, value)

def __init__(self, experiment):
    self.experiment = experiment

    def log_writer_decorator(
        instance, original_method, original_args, original_kwargs
    ):
        result = original_method(instance, *original_args, **original_kwargs)
        if "logdir" in original_kwargs:
            logdir = original_kwargs["logdir"]
        else:
            logdir = original_args[0]
        self.experiment.info.setdefault("tensorflow", {}).setdefault(
            "logdirs", []
        ).append(logdir)
        return result

    ContextMethodDecorator.__init__(
        self, tf.summary.FileWriter, "__init__", log_writer_decorator
    )

def __enter__(self):

    self.original_method = getattr(self.classx, self.method_name)
    if not hasattr(
        self.original_method, "sacred_patched%s" % self.__class__.__name__
    ):

        @functools.wraps(self.original_method)
        def decorated(instance, *args, **kwargs):
            return self.decorator_func(instance, self.original_method, args, kwargs)

        setattr(self.classx, self.method_name, decorated)
        setattr(decorated, "sacred_patched%s" % self.__class__.__name__, True)
        self.patched_by_me = True

def __exit__(self, type, value, traceback):
    if self.patched_by_me:
        # Restore original function
        setattr(self.classx, self.method_name, self.original_method)

