def save_sources(self, ex_info):
    base_dir = ex_info["base_dir"]
    source_info = []
    for s, _ in ex_info["sources"]:
        abspath = os.path.join(base_dir, s)
        if self.copy_sources:
            store_path = self.find_or_save(abspath, self.source_dir)
        else:
            store_path = abspath
        relative_source = os.path.relpath(str(store_path), self.basedir)
        source_info.append([s, relative_source])
    return source_info

def find_or_save(self, filename, store_dir: Path):
    try:
        Path(filename).resolve().relative_to(Path(self.basedir).resolve())
        is_relative_to = True
    except ValueError:
        is_relative_to = False

    if is_relative_to and not self.copy_artifacts:
        return filename
    else:
        store_dir.mkdir(parents=True, exist_ok=True)
        source_name, ext = os.path.splitext(os.path.basename(filename))
        md5sum = get_digest(filename)
        store_name = source_name + "_" + md5sum + ext
        store_path = store_dir / store_name
        if not store_path.exists():
            copyfile(filename, str(store_path))
        return store_path

def force_valid_bson_key(key):
    key = str(key)
    if key.startswith("$"):
        key = "@" + key[1:]
    key = key.replace(".", ",")
    return key

def force_bson_encodeable(obj):
    import bson

    if isinstance(obj, dict):
        try:
            bson.BSON.encode(obj, check_keys=True)
            return obj
        except bson.InvalidDocument:
            return {
                force_valid_bson_key(k): force_bson_encodeable(v)
                for k, v in obj.items()
            }

    elif opt.has_numpy and isinstance(obj, opt.np.ndarray):
        return obj
    else:
        try:
            bson.BSON.encode({"dict_just_for_testing": obj})
            return obj
        except bson.InvalidDocument:
            return str(obj)

def _try_to_detect_content_type(filename):
    mime_type, _ = mimetype_detector.guess_type(filename)
    if mime_type is not None:
        print(
            "Added {} as content-type of artifact {}.".format(mime_type, filename)
        )
    else:
        print(
            "Failed to detect content-type automatically for "
            "artifact {}.".format(filename)
        )
    return mime_type

def parse_mongo_db_arg(mongo_db):
    g = re.match(get_pattern(), mongo_db).groupdict()
    if g is None:
        raise ValueError(
            'mongo_db argument must have the form "db_name" '
            'or "host:port[:db_name]" but was {}'.format(mongo_db)
        )

    kwargs = {}
    if g["host1"]:
        kwargs["url"] = "{}:{}".format(g["host1"], g["port1"])
    elif g["host2"]:
        kwargs["url"] = "{}:{}".format(g["host2"], g["port2"])

    if g["priority"] is not None:
        kwargs["priority"] = int(g["priority"])

    for p in ["db_name", "collection", "overwrite"]:
        if g[p] is not None:
            kwargs[p] = g[p]

    return kwargs

def save(self):
    """Insert or update the current run entry."""
    if self.db_run_id:
        self.runs.update(self.run_entry, doc_ids=[self.db_run_id])
    else:
        db_run_id = self.runs.insert(self.run_entry)
        self.db_run_id = db_run_id

def search(self, *args, **kwargs):
    """Wrapper to TinyDB's search function."""
    return self.runs.search(*args, **kwargs)

def fetch_files(self, exp_name=None, query=None, indices=None):
    """Return Dictionary of files for experiment name or query.

    Returns a list of one dictionary per matched experiment. The
    dictionary is of the following structure

        {
          'exp_name': 'scascasc',
          'exp_id': 'dqwdqdqwf',
          'date': datatime_object,
          'sources': [ {'filename': filehandle}, ..., ],
          'resources': [ {'filename': filehandle}, ..., ],
          'artifacts': [ {'filename': filehandle}, ..., ]
        }

    """
    entries = self.fetch_metadata(exp_name, query, indices)

    all_matched_entries = []
    for ent in entries:

        rec = dict(
            exp_name=ent["experiment"]["name"],
            exp_id=ent["_id"],
            date=ent["start_time"],
        )

        source_files = {x[0]: x[2] for x in ent["experiment"]["sources"]}
        resource_files = {x[0]: x[2] for x in ent["resources"]}
        artifact_files = {x[0]: x[3] for x in ent["artifacts"]}

        if source_files:
            rec["sources"] = source_files
        if resource_files:
            rec["resources"] = resource_files
        if artifact_files:
            rec["artifacts"] = artifact_files

        all_matched_entries.append(rec)

    return all_matched_entries

def fetch_metadata(self, exp_name=None, query=None, indices=None):
    """Return all metadata for matching experiment name, index or query."""
    from tinydb import Query

    if exp_name or query:
        if query:
            q = query
        elif exp_name:
            q = Query().experiment.name.search(exp_name)

        entries = self.runs.search(q)

    elif indices or indices == 0:
        if not isinstance(indices, (tuple, list)):
            indices = [indices]

        num_recs = len(self.runs)

        for idx in indices:
            if idx >= num_recs:
                raise ValueError(
                    "Index value ({}) must be less than "
                    "number of records ({})".format(idx, num_recs)
                )

        entries = [self.runs.all()[ind] for ind in indices]

    else:
        raise ValueError(
            "Must specify an experiment name, indicies or " "pass custom query"
        )

    return entries

def recursive_fill_in(config, preset):
    for key in preset:
        if key not in config:
            config[key] = preset[key]
        elif isinstance(config[key], dict) and isinstance(preset[key], dict):
            recursive_fill_in(config[key], preset[key])

def chain_evaluate_config_scopes(config_scopes, fixed=None, preset=None, fallback=None):
    fixed = fixed or {}
    fallback = fallback or {}
    final_config = dict(preset or {})
    config_summaries = []
    for config in config_scopes:
        cfg = config(fixed=fixed, preset=final_config, fallback=fallback)
        config_summaries.append(cfg)
        final_config.update(cfg)

    if not config_scopes:
        final_config.update(fixed)

    return undogmatize(final_config), config_summaries

def dogmatize(obj):
    if isinstance(obj, dict):
        return DogmaticDict({key: dogmatize(val) for key, val in obj.items()})
    elif isinstance(obj, list):
        return DogmaticList([dogmatize(value) for value in obj])
    elif isinstance(obj, tuple):
        return tuple(dogmatize(value) for value in obj)
    else:
        return obj

def undogmatize(obj):
    if isinstance(obj, DogmaticDict):
        return dict({key: undogmatize(value) for key, value in obj.items()})
    elif isinstance(obj, DogmaticList):
        return list([undogmatize(value) for value in obj])
    elif isinstance(obj, tuple):
        return tuple(undogmatize(value) for value in obj)
    else:
        return obj

def __setitem__(self, key, value):
    if key not in self.fixed:
        if key in self.fallback:
            self.fallback_writes.append(key)
        return dict.__setitem__(self, key, value)

    fixed_value = self.fixed[key]
    dict.__setitem__(self, key, fixed_value)
    # if both are dicts do a recursive update
    if isinstance(fixed_value, DogmaticDict) and isinstance(value, dict):
        for k, val in value.items():
            fixed_value[k] = val

    self._log_blocked_setitem(key, value, fixed_value)

def __getitem__(self, item):
    if dict.__contains__(self, item):
        return dict.__getitem__(self, item)
    elif item in self.fallback:
        if item in self.fixed:
            return self.fixed[item]
        else:
            return self.fallback[item]
    raise KeyError(item)

def get(self, k, d=None):
    if dict.__contains__(self, k):
        return dict.__getitem__(self, k)
    else:
        return self.fallback.get(k, d)

def revelation(self):
    missing = set()
    for key in self.fixed:
        if not dict.__contains__(self, key):
            self[key] = self.fixed[key]
            missing.add(key)

        if isinstance(self[key], (DogmaticDict, DogmaticList)):
            missing |= {key + "." + k for k in self[key].revelation()}
    return missing

def _log_blocked_setitem(self, key, value, fixed_value):
    if type_changed(value, fixed_value):
        self.typechanges[key] = (type(value), type(fixed_value))

    if is_different(value, fixed_value):
        self.modified.add(key)

    # if both are dicts recursively collect modified and typechanges
    if isinstance(fixed_value, DogmaticDict) and isinstance(value, dict):
        for k, val in fixed_value.typechanges.items():
            self.typechanges[join_paths(key, k)] = val

        self.modified |= {join_paths(key, m) for m in fixed_value.modified}

def is_different(old_value, new_value):
    """Numpy aware comparison between two values."""
    if opt.has_numpy:
        return not opt.np.array_equal(old_value, new_value)
    else:
        return old_value != new_value

def __delitem__(self, key):
    if key not in self.fixed:
        dict.__delitem__(self, key)

def update(self, iterable=None, **kwargs):
    if iterable is not None:
        if hasattr(iterable, "keys"):
            for key in iterable:
                self[key] = iterable[key]
        else:
            for (key, value) in iterable:
                self[key] = value
    for key in kwargs:
        self[key] = kwargs[key]

def __deepcopy__(self, memo):
    d = dict(self)
    return copy.deepcopy(d, memo=memo)

def __deepcopy__(self, memo):
    lst = list(self)
    return copy.deepcopy(lst, memo=memo)

def read_only_dict_representer(dumper, data):
    """Saves `ReadOnlyDict` as `dict`."""
    return dumper.represent_dict(data)

def read_only_list_representer(dumper, data):
    """Saves `ReadOnlyList` as `list`."""
    return dumper.represent_list(data)

def is_empty_or_comment(line):
    sline = line.strip()
    return sline == "" or sline.startswith("#")

def dedent_line(line, indent):
    for i, (line_sym, indent_sym) in enumerate(zip(line, indent)):
        if line_sym != indent_sym:
            start = i
            break
    else:
        start = len(indent)
    return line[start:]

def dedent_function_body(body):
    lines = body.split("\n")
    # find indentation by first line
    indent = ""
    for line in lines:
        if is_empty_or_comment(line):
            continue
        else:
            indent = re.match(r"^\s*", line).group()
            break

    out_lines = [dedent_line(line, indent) for line in lines]
    return "\n".join(out_lines)

def get_function_body_code(func):
    filename = inspect.getfile(func)
    func_body, line_offset = get_function_body(func)
    body_source = dedent_function_body(func_body)
    try:
        body_code = compile(body_source, filename, "exec", ast.PyCF_ONLY_AST)
        body_code = ast.increment_lineno(body_code, n=line_offset)
        body_code = compile(body_code, filename, "exec")
    except SyntaxError as e:
        if e.args[0] == "'return' outside function":
            filename, lineno, _, statement = e.args[1]
            raise SyntaxError(
                "No return statements allowed in ConfigScopes\n"
                "('{}' in File \"{}\", line {})".format(
                    statement.strip(), filename, lineno
                )
            ) from e
        elif e.args[0] == "'yield' outside function":
            filename, lineno, _, statement = e.args[1]
            raise SyntaxError(
                "No yield statements allowed in ConfigScopes\n"
                "('{}' in File \"{}\", line {})".format(
                    statement.strip(), filename, lineno
                )
            ) from e
        else:
            raise
    return body_code

def get_config_comments(func):
    filename = inspect.getfile(func)
    func_body, line_offset = get_function_body(func)
    body_source = dedent_function_body(func_body)
    body_code = compile(body_source, filename, "exec", ast.PyCF_ONLY_AST)
    body_lines = body_source.split("\n")

    variables = {"seed": "the random seed for this experiment"}

    for ast_root in body_code.body:
        for ast_entry in [ast_root] + list(ast.iter_child_nodes(ast_root)):
            if isinstance(ast_entry, ast.Assign):
                # we found an assignment statement
                # go through all targets of the assignment
                # usually a single entry, but can be more for statements like:
                # a = b = 5
                for t in ast_entry.targets:
                    add_doc(t, variables, body_lines)

    return variables

def is_ignored(line):
    for pattern in SETTINGS.CONFIG.IGNORED_COMMENTS:
        if re.match(pattern, line) is not None:
            return True
    return False

def find_doc_for(ast_entry, body_lines):
    lineno = ast_entry.lineno - 1
    line_io = io.BytesIO(body_lines[lineno].encode())
    try:
        tokens = tokenize(line_io.readline) or []
        line_comments = [token.string for token in tokens if token.type == COMMENT]

        if line_comments:
            formatted_lcs = [line[1:].strip() for line in line_comments]
            filtered_lcs = [line for line in formatted_lcs if not is_ignored(line)]
            if filtered_lcs:
                return filtered_lcs[0]
    except TokenError:
        pass

    lineno -= 1
    while lineno >= 0:
        if iscomment(body_lines[lineno]):
            comment = body_lines[lineno].strip("# ")
            if not is_ignored(comment):
                return comment
        if not body_lines[lineno].strip() == "":
            return None
        lineno -= 1
    return None

def add_doc(target, variables, body_lines):
    if isinstance(target, ast.Name):
        # if it is a variable name add it to the doc
        name = target.id
        if name not in variables:
            doc = find_doc_for(target, body_lines)
            if doc is not None:
                variables[name] = doc
    elif isinstance(target, ast.Tuple):
        # if it is a tuple then iterate the elements
        # this can happen like this:
        # a, b = 1, 2
        for e in target.elts:
            add_doc(e, variables, body_lines)

def get_free_parameters(self, args, kwargs, bound=False):
    expected_args = self._get_expected_args(bound)
    return [a for a in expected_args[len(args) :] if a not in kwargs]

def _get_expected_args(self, bound):
    if bound:
        # When called as instance method, the instance ('self') will be
        # passed as first argument automatically, so the first argument
        # should be excluded from the signature during this invocation.
        return self.arguments[1:]
    else:
        return self.arguments

def _assert_no_unexpected_args(self, expected_args, args):
    if not self.vararg_name and len(args) > len(expected_args):
        unexpected_args = args[len(expected_args) :]
        raise SignatureError(
            "{} got unexpected argument(s): {}".format(self.name, unexpected_args)
        )

def _assert_no_unexpected_kwargs(self, expected_args, kwargs):
    if self.kw_wildcard_name:
        return
    unexpected_kwargs = set(kwargs) - set(expected_args)
    if unexpected_kwargs:
        raise SignatureError(
            "{} got unexpected kwarg(s): {}".format(
                self.name, sorted(unexpected_kwargs)
            )
        )

def _assert_no_duplicate_args(self, expected_args, args, kwargs):
    positional_arguments = expected_args[: len(args)]
    duplicate_arguments = [v for v in positional_arguments if v in kwargs]
    if duplicate_arguments:
        raise SignatureError(
            "{} got multiple values for argument(s) {}".format(
                self.name, duplicate_arguments
            )
        )

def _fill_in_options(self, args, kwargs, options, bound):
    free_params = self.get_free_parameters(args, kwargs, bound)
    new_kwargs = dict(kwargs) if free_params else kwargs
    for param in free_params:
        if param in options:
            new_kwargs[param] = options[param]
    return args, new_kwargs

def _assert_no_missing_args(self, args, kwargs, bound):
    free_params = self.get_free_parameters(args, kwargs, bound)
    missing_args = [m for m in free_params if m not in self.kwargs]
    if missing_args:
        raise MissingConfigError(
            "{} is missing value(s):".format(self.name),
            missing_configs=missing_args,
        )

def normalize_numpy(obj):
    if opt.has_numpy and isinstance(obj, opt.np.generic):
        try:
            return obj.item()
        except ValueError:
            pass
    return obj

def normalize_or_die(obj):
    if isinstance(obj, dict):
        res = dict()
        for key, value in obj.items():
            assert_is_valid_key(key)
            res[key] = normalize_or_die(value)
        return res
    elif isinstance(obj, (list, tuple)):
        return list([normalize_or_die(value) for value in obj])
    return normalize_numpy(obj)
